//! Fjall-backed journal implementation.
//!
//! Provides the main storage interface for workflow artifacts,
//! run metadata, journal events, snapshots, and blobs.

use std::path::Path;
use std::sync::Mutex;
#[cfg(test)]
use std::sync::atomic::{AtomicBool, Ordering};

use crate::{
    constants::{
        KEYSPACE_ARTIFACT_ACCEPTANCE, KEYSPACE_BLOB, KEYSPACE_COMPILED_IR, KEYSPACE_EMERGENCY_DENY,
        KEYSPACE_INDEX_ACTION, KEYSPACE_INDEX_STATUS, KEYSPACE_INDEX_WORKFLOW, KEYSPACE_RUN_EVENT,
        KEYSPACE_RUN_HEADER, KEYSPACE_RUN_INPUTS, KEYSPACE_RUN_SNAPSHOT, KEYSPACE_WORKFLOW_SOURCE,
    },
    error::JournalError,
    process_lock::ProcessLock,
    types::{FjallConfig, KeyspaceProfile},
};

/// Bounded replay limit for journal event collection.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EventReplayLimit {
    max_events: usize,
}

impl EventReplayLimit {
    /// Conservative default for operator-facing replay collection.
    pub const DEFAULT: Self = Self { max_events: 65_536 };

    /// Creates a replay limit; returns `None` when the limit is zero.
    #[must_use]
    pub const fn new(max_events: usize) -> Option<Self> {
        if max_events == 0 {
            None
        } else {
            Some(Self { max_events })
        }
    }

    /// Returns the maximum number of events that may be collected.
    #[must_use]
    pub const fn max_events(self) -> usize {
        self.max_events
    }
}

/// Fjall-backed append journal.
pub struct FjallJournal {
    pub(crate) database: fjall::Database,
    pub(crate) workflow_source: fjall::Keyspace,
    pub(crate) compiled_ir: fjall::Keyspace,
    pub(crate) run_header: fjall::Keyspace,
    pub(crate) run_inputs: fjall::Keyspace,
    pub(crate) events: fjall::Keyspace,
    pub(crate) run_snapshot: fjall::Keyspace,
    pub(crate) blob: fjall::Keyspace,
    pub(crate) index_status: fjall::Keyspace,
    pub(crate) index_workflow: fjall::Keyspace,
    pub(crate) index_action: fjall::Keyspace,
    pub(crate) emergency_deny: fjall::Keyspace,
    pub(crate) artifact_acceptance: fjall::Keyspace,
    #[cfg(test)]
    pub(crate) fail_next_persist: AtomicBool,
    #[cfg(test)]
    pub(crate) fail_next_compiled_ir_readback: AtomicBool,
    /// Test-only fault hook: forces the next `JournalWriteBatch::commit()`
    /// (the path `append_strict` uses) to return `Err(JournalError::Fjall(..))`
    /// WITHOUT touching the real Fjall store. This proves the `append_strict`
    /// commit-failure contract: the staged event is never made visible and a
    /// retry is idempotent. Consumed exactly once.
    #[cfg(test)]
    pub(crate) fail_next_batch_commit: AtomicBool,
    // SAFETY: write_lock is used in append_unfsynced() for poison detection.
    // The lock guard is acquired and dropped, never read directly.
    pub(crate) write_lock: Mutex<()>,
    pub(crate) _process_lock: ProcessLock,
}

impl FjallJournal {
    /// Opens or creates the journal at `path`.
    ///
    /// When `config` is `Some`, the cache size is validated against the
    /// bounds in [`FjallConfig::MIN_CACHE_SIZE_BYTES`] /
    /// [`FjallConfig::MAX_CACHE_SIZE_BYTES`]. Out-of-range values return
    /// [`JournalError::InvalidConfig`] before any Fjall call.
    pub fn open(path: impl AsRef<Path>, config: Option<FjallConfig>) -> Result<Self, JournalError> {
        let config = config.unwrap_or_default();
        if config.cache_size_bytes < crate::types::FjallConfig::MIN_CACHE_SIZE_BYTES
            || config.cache_size_bytes > crate::types::FjallConfig::MAX_CACHE_SIZE_BYTES
        {
            return Err(JournalError::InvalidConfig {
                field: "cache_size_bytes",
                reason: "cache size must be in [MIN_CACHE_SIZE_BYTES, MAX_CACHE_SIZE_BYTES]",
